<script>export let form;</script><section class="page form-wrap"><div class="eyebrow">ANIMAL HELP</div><h1>Request community help</h1><p class="sub">Describe what you see and where help is needed. For emergencies, contact local emergency/veterinary services directly.</p>{#if form?.error}<div class="error">{form.error}</div>{/if}<form class="form" method="POST" enctype="multipart/form-data"><label>Animal</label><select name="animal_type"><option value="dog">Dog</option><option value="cat">Cat</option></select><label>Title</label><input name="title" required maxlength="120" placeholder="e.g. Injured dog near Main Road"/><label>Description</label><textarea name="description" required placeholder="What happened? What can you see? Avoid diagnosing the animal."></textarea><label>Location</label><input name="location" required maxlength="160" placeholder="Area / landmark"/><label>Photo</label><input type="file" name="image" accept="image/*"/><button class="btn primary">Post help request</button></form></section>
